import java.io.*;
import java.util.*;

public class Main {
    private static final int BUFSIZE = 8192;

    public static void main(String[] args) throws Exception {
        vsInput();

        int[] value = value();
        int h = value[0], n = value[1];

        int low = 1;
        int high = 1 << h;

        int ans = 0;
        boolean move = false;

        while (low < high) {
            int mid = low + (high - low) / 2;

            if (n <= mid) {
                if (!move) {
                    ans += 1;
                    move = !move;
                } else {
                    ans += 1 << h;
                }
                high = mid;
            } else {
                if (move) {
                    ans += 1;
                    move = !move;
                } else {
                    ans += 1 << h;
                }
                low = mid + 1;
            }

            h--;
            move ^= true;
        }

        System.out.println(ans);
    }

    private static void vsInput() throws Exception {
        System.setIn(new FileInputStream("input.txt"));
        System.setOut(new PrintStream(new File("output.txt")));
    }

    private static int[] value() throws Exception {
        return Arrays.stream(System.console().readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    }
}
